"""Regression coverage for the behavior specified in SPEC.md."""

import pytest

from sales_dashboard.loader import (
    daily_conversion_counts,
    dedupe_sessions,
    parse_session_log,
)
from sales_dashboard.metrics import (
    conversion_rate,
    conversion_rate_by_group,
    conversions_in_window,
    longest_conversion_streak,
    pooled_conversion_rate,
)
from sales_dashboard.report import campaign_summary, top_converting_groups


def session(id_, day, converted):
    return {"id": id_, "day": day, "converted": converted}


def test_conversion_rate_none_counts_in_denominator():
    events = [session("a", 1, True), session("b", 1, None), session("c", 1, False)]
    assert conversion_rate(events) == pytest.approx(1 / 3)
    assert conversion_rate([session("a", 1, None)]) == 0.0


def test_conversion_rate_empty_is_float_zero():
    result = conversion_rate([])
    assert result == 0.0
    assert isinstance(result, float)


def test_pooled_conversion_rate_weights_sessions_not_groups():
    groups = {
        "small": [session("a", 1, True)],
        "large": [session("b", 1, True), session("c", 1, False), session("d", 1, None)],
        "empty": [],
    }
    assert pooled_conversion_rate(groups) == 0.5


@pytest.mark.parametrize("groups", [{}, {"empty": []}, {"a": [], "b": []}])
def test_empty_groups(groups):
    assert pooled_conversion_rate(groups) == 0.0
    assert campaign_summary(groups, 3) == {"rate": 0.0, "recent": 0, "groups": 0}
    assert top_converting_groups(groups, 3) == []


@pytest.mark.parametrize(
    "counts, days, expected",
    [([1, 2, 4], 0, 0), ([1, 2, 4], 1, 4), ([1, 2, 4], 2, 6),
     ([1, 2, 4], 3, 7), ([1, 2, 4], 10, 7), ([], 2, 0), ([], 0, 0)],
)
def test_conversions_in_window(counts, days, expected):
    assert conversions_in_window(counts, days) == expected


def test_parse_session_log_flags_whitespace_and_skipped_lines():
    lines = ["", " \t\n", "#comment", "  # ignored,not,a,record", " a , 2 , 1 \n",
             " b , -3 , 0 ", " c , 4 , \t"]
    assert parse_session_log(lines) == [
        session("a", 2, True), session("b", -3, False), session("c", 4, None)
    ]
    assert parse_session_log([]) == []


@pytest.mark.parametrize("bad_line", ["a,1", "a,1,0,extra", "a,no,1", "a,1.5,0", "a,,1"])
def test_parse_session_log_errors_include_original_line_number(bad_line):
    with pytest.raises(ValueError, match=r"\bline 5\b"):
        parse_session_log(["# comment", "", "a,1,1", "  \t", bad_line])


def test_dedupe_sessions_keeps_last_duplicate_id_and_sorts():
    events = [
        session("b", 9, True), session("a", 3, True), session("c", 1, None),
        session("b", 3, False), session("a", 8, False), session("a", 3, None),
    ]
    assert dedupe_sessions(events) == [events[2], events[5], events[3]]
    assert dedupe_sessions([]) == []


def test_daily_conversion_counts_inclusive_filled_and_filtered():
    events = [
        session("before", 0, True), session("start", 1, True),
        session("false", 2, False), session("none", 2, None),
        session("end1", 4, True), session("end2", 4, True),
        session("after", 5, True),
    ]
    assert daily_conversion_counts(events, 1, 4) == [1, 0, 0, 2]
    assert daily_conversion_counts(events, 4, 4) == [2]
    assert daily_conversion_counts(events, 4, 1) == []
    assert daily_conversion_counts([], -1, 1) == [0, 0, 0]


@pytest.mark.parametrize("days, recent", [(0, 0), (1, 0), (2, 1), (3, 1), (20, 2)])
def test_campaign_summary_pooled_rounded_calendar_window(days, recent):
    groups = {
        "small": [session("a", 1, True)],
        "large": [session("b", 4, True), session("c", 5, False)],
        "empty": [],
    }
    assert campaign_summary(groups, days) == {"rate": 0.667, "recent": recent, "groups": 2}


@pytest.mark.parametrize("n, expected", [(0, []), (1, ["winner"]),
                                         (3, ["winner", "alpha", "zeta"]),
                                         (10, ["winner", "alpha", "zeta", "zero"])])
def test_top_converting_groups_excludes_empty_and_breaks_ties_by_name(n, expected):
    groups = {
        "zeta": [session("a", 1, True), session("b", 1, None)],
        "empty": [],
        "zero": [session("c", 1, False)],
        "winner": [session("d", 1, True)],
        "alpha": [session("e", 1, False), session("f", 1, True)],
    }
    assert top_converting_groups(groups, n) == expected


def test_conversion_rate_by_group_sorted_with_empty_none():
    groups = {"z": [], "b": [session("b", 1, None)],
              "a": [session("a", 1, True), session("c", 1, False)]}
    result = conversion_rate_by_group(groups)
    assert result == {"a": 0.5, "b": 0.0, "z": None}
    assert list(result) == ["a", "b", "z"]
    assert conversion_rate_by_group({}) == {}


@pytest.mark.parametrize(
    "counts, expected",
    [([], 0), ([0, -1, 0], 0), ([1, 2, 0, 3], 2), ([1, -1, 2], 1),
     ([0, 1, 2, 3], 3), ([1, 2, 3, 0], 3)],
)
def test_longest_conversion_streak(counts, expected):
    assert longest_conversion_streak(counts) == expected
